-- search_area_seed_sorted_clamped.sql
-- Original entries, only coordinates clamped to lon [-180,180], lat [-90,90]
-- Ordered by name: I, II, III, IV, V, VI, VII, VIII, IX, X, XI, XII, XII, XIII, XIII, XIV, XIV, XV, XVI, XVII, XVIII, XIX, XX, XXI, XXI, XXII, XXIII, XXIV

CREATE TABLE IF NOT EXISTS search_area (
                                           id SERIAL PRIMARY KEY,
                                           name TEXT NOT NULL,
                                           geometry GEOMETRY(MULTIPOLYGON, 4326)
);

CREATE TABLE instance_search_area (
                                      instance_id     BIGINT NOT NULL,
                                      search_area_id  BIGINT NOT NULL,
    -- prevent duplicates
                                      PRIMARY KEY (instance_id, search_area_id),

                                      CONSTRAINT fk_isa_instance
                                          FOREIGN KEY (instance_id) REFERENCES public.instance(id) ON DELETE CASCADE,
                                      CONSTRAINT fk_isa_search_area
                                          FOREIGN KEY (search_area_id) REFERENCES search_area(id) ON DELETE CASCADE
);

